CREATE FUNCTION score_scope_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT (EXISTS(SELECT 1 FROM enrollment e JOIN section s ON s.id=e.section_id JOIN term t ON t.id=NEW.term_id JOIN offering o ON o.id=NEW.offering_id WHERE e.id=NEW.enrollment_id AND e.year_id=t.year_id AND s.grade_id=o.grade_id AND NEW.value<=o.maximum)) THEN RAISE EXCEPTION 'score_scope'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER score_scope BEFORE INSERT ON score FOR EACH ROW EXECUTE FUNCTION score_scope_fn();
CREATE FUNCTION assignment_scope_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT (EXISTS(SELECT 1 FROM section s JOIN offering o ON o.grade_id=s.grade_id WHERE s.id=NEW.section_id AND o.id=NEW.offering_id)) THEN RAISE EXCEPTION 'assignment_scope'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER assignment_scope BEFORE INSERT ON assignment FOR EACH ROW EXECUTE FUNCTION assignment_scope_fn();
CREATE FUNCTION result_run_update_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='APPROVED' THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER result_run_update_immutable BEFORE UPDATE ON result_run FOR EACH ROW EXECUTE FUNCTION result_run_update_immutable_fn();
CREATE FUNCTION result_run_delete_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='APPROVED' THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN OLD; END; $$;
CREATE TRIGGER result_run_delete_immutable BEFORE DELETE ON result_run FOR EACH ROW EXECUTE FUNCTION result_run_delete_immutable_fn();
CREATE FUNCTION student_result_update_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM result_run r WHERE r.id=OLD.run_id AND r.status='APPROVED') THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER student_result_update_immutable BEFORE UPDATE ON student_result FOR EACH ROW EXECUTE FUNCTION student_result_update_immutable_fn();
CREATE FUNCTION student_result_delete_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM result_run r WHERE r.id=OLD.run_id AND r.status='APPROVED') THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN OLD; END; $$;
CREATE TRIGGER student_result_delete_immutable BEFORE DELETE ON student_result FOR EACH ROW EXECUTE FUNCTION student_result_delete_immutable_fn();
CREATE FUNCTION result_mark_update_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM student_result s JOIN result_run r ON r.id=s.run_id WHERE s.id=OLD.student_result_id AND r.status='APPROVED') THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER result_mark_update_immutable BEFORE UPDATE ON result_mark FOR EACH ROW EXECUTE FUNCTION result_mark_update_immutable_fn();
CREATE FUNCTION result_mark_delete_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM student_result s JOIN result_run r ON r.id=s.run_id WHERE s.id=OLD.student_result_id AND r.status='APPROVED') THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN OLD; END; $$;
CREATE TRIGGER result_mark_delete_immutable BEFORE DELETE ON result_mark FOR EACH ROW EXECUTE FUNCTION result_mark_delete_immutable_fn();
CREATE FUNCTION report_template_update_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='APPROVED' THEN RAISE EXCEPTION 'immutable_record'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER report_template_update_immutable BEFORE UPDATE ON report_template FOR EACH ROW EXECUTE FUNCTION report_template_update_immutable_fn();
